<template><div class="interaction-cell"><el-button type="text" :disabled="!primary.id" @click="open(primary)">{{ title }}</el-button><div v-if="log.id" :class="resultTone(log.result)">{{ actions[log.action] || log.action }} · {{ results[log.result] || log.result }}</div><div v-if="log.id" class="muted">{{ log.create_time }}</div><div class="danger" v-if="log.error_info">{{ log.error_info }}</div><el-button v-if="log.id" size="mini" type="text" @click="open(primary)">查看交互</el-button><span v-else class="muted">{{ executions.length?'尚无仓库交互记录':'尚未生成入库执行单' }}</span></div></template>
<script>
import { actions, results, resultTone } from '../warehouse/wmsLogLabels'
export default { props: { row: { type: Object, required: true } }, data: () => ({ actions, results }), computed: { executions() { return (this.row.warehouseExecutions || [this.row]).filter(x => x.interactionSn) }, primary() { return this.executions.slice().sort((a,b) => Number((b.latestInteraction||{}).id||0)-Number((a.latestInteraction||{}).id||0))[0] || {} }, log() { return this.primary.latestInteraction || {} }, title() { const labels=[...new Set(this.executions.map(x=>x.warehouseLabel).filter(Boolean))];return labels.join(' / ')+(this.executions.length>1?'（'+this.executions.length+'张执行单）':'')||'待建立执行单' } }, methods: { resultTone, open(row) { if(row.id)this.$emit('open',{...row,id:row.ticketId||row.id}) } } }
</script>
<style scoped>.interaction-cell{font-size:12px;line-height:1.8;overflow-wrap:anywhere}.interaction-cell .el-button{white-space:normal;text-align:left}.muted{display:block;color:#7c899b}.danger{color:#c74545}.warning{color:#b77d19}.success{color:#278558}</style>
